<script setup>
import { ref, onMounted, onUnmounted, nextTick } from 'vue'
const section=ref('characters'), characters=ref([]), jokes=ref([]), activities=ref([]), busy=ref({}), errors=ref({}), query=ref({characters:'',jokes:'',activities:''}), filters=ref({characters:'all',jokes:'Any',activities:'all'}), pages=ref({characters:1}), selected=ref(null), menu=ref(false)
const characterStatuses=['all','alive','dead','unknown'], jokeCategories=['Any','Programming','Misc','Pun','Spooky','Christmas'], activityTypes=['all','education','recreational','social','diy','charity','cooking','relaxation','music','busywork']
function characterImage(character){
 const id=Number(character?.id)
 return Number.isSafeInteger(id)&&id>0?'/api/avatar?id='+id:'/avatar-fallback.svg'
}
function imageFailed(event){
 const el=event.target
 if(el && !el.src.endsWith('/avatar-fallback.svg'))el.src='/avatar-fallback.svg'
}
const requestIds={characters:0,jokes:0,activities:0}
const pageCount=ref(1)
const copied=ref(false),activitySource=ref(''),modalClose=ref(null),returnFocus=ref(null)
async function copyJoke(j){try{await navigator.clipboard.writeText(j.type==='twopart'?j.setup+' — '+j.delivery:j.joke);copied.value=true;setTimeout(()=>copied.value=false,1800)}catch{copied.value=false}}
function showDetails(kind,item){returnFocus.value=document.activeElement;selected.value={kind,...item};document.body.style.overflow='hidden';nextTick(()=>modalClose.value?.focus())}
function closeDetails(){selected.value=null;document.body.style.overflow='';nextTick(()=>returnFocus.value?.focus?.())}
function onKey(e){if(e.key==='Escape'&&selected.value)closeDetails();if(e.key==='Tab'&&selected.value){const dialog=document.querySelector('.modal');const els=[...dialog.querySelectorAll('button,a[href],input,[tabindex]:not([tabindex="-1"])')].filter(el=>!el.disabled);if(!els.length)return;const first=els[0],last=els[els.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}}
onUnmounted(()=>{Object.values(timers).forEach(clearTimeout);document.removeEventListener('keydown',onKey);document.body.style.overflow=''})
const descriptions={characters:'Meet the weird and wonderful residents of the multiverse.',jokes:'A little laughter goes a long way. Find your kind of funny.',activities:'Your next great idea is just one click away.'}
async function load(key) {
 const id=++requestIds[key];busy.value={...busy.value,[key]:true};errors.value={...errors.value,[key]:''}
 try {
  const url=new URL('/api/'+key,location.origin)
  if(query.value[key]) url.searchParams.set('search',query.value[key])
  if(filters.value[key]!=='all'&&filters.value[key]!=='Any') url.searchParams.set('type',filters.value[key])
  if(key==='characters'){url.searchParams.set('status',filters.value.characters);url.searchParams.set('page',pages.value.characters)}
  const res=await fetch(url)
  if(!(res.headers.get('content-type')||'').includes('application/json'))throw Error('API returned an invalid response. Try again.')
  const data=await res.json()
  if(id!==requestIds[key])return
  if(!res.ok)throw Error(data.error||'Could not load content.')
  const value=key==='characters'?(data.results||[]):key==='jokes'?(data.jokes||[]):(data.activities||[])
  if(key==='characters'){characters.value=value;pageCount.value=data.info?.pages||1}
  if(key==='jokes')jokes.value=value
  if(key==='activities'){activities.value=value;activitySource.value=data.source||''}
 }catch(err){if(id===requestIds[key]){errors.value={...errors.value,[key]:err.message};if(key==='characters')characters.value=[];if(key==='jokes')jokes.value=[];if(key==='activities')activities.value=[]}}
 finally{if(id===requestIds[key])busy.value={...busy.value,[key]:false}}
}
let timers={}
function search(key){clearTimeout(timers[key]);pages.value.characters=1;timers[key]=setTimeout(()=>load(key),350)}
function filter(key,v){clearTimeout(timers[key]);filters.value[key]=v;pages.value.characters=1;load(key)}
function clearSearch(key){query.value[key]='';clearTimeout(timers[key]);if(key==='characters')pages.value.characters=1;load(key)}
function go(id){section.value=id;menu.value=false;document.getElementById(id)?.scrollIntoView({behavior:'smooth'})}
onMounted(()=>{document.addEventListener('keydown',onKey);load('characters');load('jokes');load('activities')})
</script>
<template>
<div class="site" id="top">
 <div class="ambient ambient-one"></div><div class="ambient ambient-two"></div>
 <header class="header shell"><a class="brand" href="#top"><span class="brand-mark">✳</span><span>VANTA <b>FUN</b></span></a><nav id="main-navigation" :class="{open:menu}"><a href="#characters" @click="menu=false">Characters</a><a href="#jokes" @click="menu=false">Jokes</a><a href="#activities" @click="menu=false">Activities</a></nav><button class="nav-cta" @click="go('characters')">Explore the fun <span>↗</span></button><button class="hamburger" :aria-expanded="menu" aria-controls="main-navigation" aria-label="Toggle navigation" @click="menu=!menu">☰</button></header>
 <main>
  <section class="hero shell"><div class="hero-copy"><div class="eyebrow"><span class="live-dot"></span> YOUR DAILY DOSE OF DISCOVERY <span class="tiny-star">✦</span></div><h1>Bored?<br><em>Not here<span class="period">.</span></em></h1><p>Explore the multiverse. Discover your next favourite joke. Find something exciting to do. All the fun, in one place.</p><div class="hero-actions"><button class="primary-btn" @click="go('characters')">Start exploring <span>↗</span></button><a href="#about" class="quiet-link">What is Vanta Fun? <span>↓</span></a></div><div class="hero-stats"><div><strong>03</strong><span>INTERACTIVE WORLDS</span></div><div><strong>∞</strong><span>POSSIBILITIES</span></div><div><strong>100%</strong><span>CURIOSITY</span></div></div></div><div class="hero-art" aria-hidden="true"><div class="orbit orbit-one"></div><div class="orbit orbit-two"></div><div class="hero-center"><span>✳</span><small>THE FUN STARTS HERE</small></div><div class="float-card float-one"><span>👽</span><small>CHARACTERS</small></div><div class="float-card float-two"><span>😂</span><small>JOKES</small></div><div class="float-card float-three"><span>🎨</span><small>ACTIVITIES</small></div><div class="spark spark-a">✦</div><div class="spark spark-b">✳</div></div></section>
  <div class="ticker"><div>THREE WORLDS <span>✳</span> INFINITE FUN <span>✳</span> NEVER A DULL MOMENT <span>✳</span> THREE WORLDS <span>✳</span> INFINITE FUN <span>✳</span> NEVER A DULL MOMENT <span>✳</span></div></div>
  <section id="characters" class="content-section shell purple"><div class="section-top"><div><div class="section-kicker"><span>01 / THE MULTIVERSE</span></div><h2>Meet the <em>characters.</em></h2><p>{{ descriptions.characters }}</p></div><span class="section-icon">👾</span></div><div class="toolbar"><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search characters</span><input v-model="query.characters" type="search" name="characters-search" autocomplete="off" aria-label="Search characters" placeholder="Search characters..." @input="search('characters')"><button v-if="query.characters" type="button" class="search-clear" aria-label="Clear characters search" @click="clearSearch('characters')">✕</button></label><div class="chips"><button v-for="status in characterStatuses" :key="status" :class="{active:filters.characters===status}" @click="filter('characters',status)">{{status}}</button></div></div><div class="result-summary" aria-live="polite"><span class="result-dot"></span>{{busy.characters?'Searching...':errors.characters?'Unable to load results':characters.length+' result'+(characters.length===1?'':'s')}} <span class="result-filter">· {{filters.characters==='all'||filters.characters==='Any'?'All categories':filters.characters}}</span></div><div v-if="busy.characters" class="cards character-grid" role="status"><div v-for="n in 8" :key="n" class="skeleton-card"><div class="skeleton-image"></div><div class="skeleton-line"></div><div class="skeleton-line short"></div></div><span class="sr-only">Loading characters...</span></div><div v-if="errors.characters" class="notice error"><span aria-hidden="true">⚠</span> {{errors.characters}} <button @click="load('characters')">Try again ↻</button></div><p v-if="!busy.characters&&!errors.characters&&!characters.length" class="notice">No characters found. Try another search or status.</p><div v-if="!busy.characters&&!errors.characters" class="cards character-grid"><button v-for="c in characters" :key="c.id" class="content-card character-card" @click="showDetails('character',c)"><img :src="characterImage(c)" :alt="c.name" loading="lazy" @error="imageFailed"><div class="card-content"><span class="card-meta"><i :class="(c.status||'').toLowerCase()"></i>{{c.status||'Unknown'}} · {{c.species||'Unknown'}}</span><h3>{{c.name}}</h3><span class="card-link">View profile ↗</span></div></button></div><div class="section-actions"><button class="secondary-btn" :disabled="pages.characters<=1||busy.characters" @click="pages.characters--;load('characters')">← Previous</button><span>PAGE {{pages.characters}}</span><button class="secondary-btn" :disabled="busy.characters||pages.characters>=pageCount" @click="pages.characters++;load('characters')">Next →</button></div></section>
  <section id="jokes" class="content-section shell yellow"><div class="section-top"><div><div class="section-kicker">02 / LAUGH A LITTLE</div><h2>Life's better <em>with laughs.</em></h2><p>{{descriptions.jokes}}</p></div><span class="section-icon">😆</span></div><div class="toolbar"><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search jokes</span><input v-model="query.jokes" type="search" name="jokes-search" autocomplete="off" aria-label="Search jokes" placeholder="Search jokes..." @input="search('jokes')"><button v-if="query.jokes" type="button" class="search-clear" aria-label="Clear jokes search" @click="clearSearch('jokes')">✕</button></label><div class="chips"><button v-for="cat in jokeCategories" :key="cat" :class="{active:filters.jokes===cat}" @click="filter('jokes',cat)">{{cat}}</button></div></div><div class="result-summary" aria-live="polite"><span class="result-dot"></span>{{busy.jokes?'Searching...':errors.jokes?'Unable to load results':jokes.length+' result'+(jokes.length===1?'':'s')}} <span class="result-filter">· {{filters.jokes==='all'||filters.jokes==='Any'?'All categories':filters.jokes}}</span></div><div v-if="busy.jokes" class="cards joke-grid" role="status"><div v-for="n in 6" :key="n" class="skeleton-card"><div class="skeleton-line"></div><div class="skeleton-line"></div><div class="skeleton-line short"></div></div><span class="sr-only">Loading jokes...</span></div><div v-if="errors.jokes" class="notice error"><span aria-hidden="true">⚠</span> {{errors.jokes}} <button @click="load('jokes')">Try again ↻</button></div><p v-if="!busy.jokes&&!errors.jokes&&!jokes.length" class="notice">No jokes matched your search. Try another category.</p><div v-if="!busy.jokes&&!errors.jokes" class="cards joke-grid"><article v-for="(j,i) in jokes" :key="j.id||i" class="content-card joke-card"><div class="card-meta">{{j.category||'Joke'}} <span>✳</span></div><h3>{{j.type==='twopart'?j.setup:j.joke}}</h3><p v-if="j.type==='twopart'" class="punchline">{{j.delivery}}</p><div class="joke-bottom"><button class="detail-link" @click="showDetails('joke',j)">Read details ↗</button><button @click="copyJoke(j)" class="copy-btn" title="Copy joke">↗</button></div></article></div><div class="section-actions"><button class="primary-btn yellow-btn" :disabled="busy.jokes" @click="load('jokes')">Shuffle the laughs ↻</button></div></section>
  <section id="activities" class="content-section shell blue"><div class="section-top"><div><div class="section-kicker">03 / MAKE A MEMORY</div><h2>Go do <em>something.</em></h2><p>{{descriptions.activities}}</p></div><span class="section-icon">⚡</span></div><div class="toolbar"><label class="search"><span aria-hidden="true">⌕</span><span class="sr-only">Search activities</span><input v-model="query.activities" type="search" name="activities-search" autocomplete="off" aria-label="Search activities" placeholder="Find an activity..." @input="search('activities')"><button v-if="query.activities" type="button" class="search-clear" aria-label="Clear activities search" @click="clearSearch('activities')">✕</button></label><div class="chips"><button v-for="type in activityTypes" :key="type" :class="{active:filters.activities===type}" @click="filter('activities',type)">{{type}}</button></div></div><div class="result-summary" aria-live="polite"><span class="result-dot"></span>{{busy.activities?'Searching...':errors.activities?'Unable to load results':activities.length+' result'+(activities.length===1?'':'s')}} <span class="result-filter">· {{filters.activities==='all'||filters.activities==='Any'?'All categories':filters.activities}}</span></div><p v-if="!busy.activities&&!errors.activities&&activitySource==='curated suggestions'" class="source-note">✦ Showing curated suggestions when API results are unavailable or do not match.</p><div v-if="busy.activities" class="cards activity-grid" role="status"><div v-for="n in 6" :key="n" class="skeleton-card"><div class="skeleton-line"></div><div class="skeleton-line"></div><div class="skeleton-line short"></div></div><span class="sr-only">Loading activities...</span></div><div v-if="errors.activities" class="notice error"><span aria-hidden="true">⚠</span> {{errors.activities}} <button @click="load('activities')">Try again ↻</button></div><p v-if="!busy.activities&&!errors.activities&&!activities.length" class="notice">No activities found. Try another category.</p><div v-if="!busy.activities&&!errors.activities" class="cards activity-grid"><article v-for="(a,i) in activities" :key="a.key||i" class="content-card activity-card"><div class="activity-number">{{String(i+1).padStart(2,'0')}}</div><span class="card-meta">{{a.type||'Activity'}}</span><h3>{{a.activity}}</h3><div class="activity-foot"><span>{{a.participants||1}} participant{{(a.participants||1)>1?'s':''}}</span><button class="detail-link" @click="showDetails('activity',a)">View details ↗</button></div></article></div><div class="section-actions"><button class="primary-btn blue-btn" :disabled="busy.activities" @click="load('activities')">Surprise me ↻</button></div></section>
 </main><footer id="about" class="footer"><div class="shell footer-main"><div><div class="brand"><span class="brand-mark">✳</span>VANTA <b>FUN</b></div><h2>Fun looks good<br><em>on you.</em></h2><p>One page, three escapes. Built with Vue 3, powered by public APIs and curiosity.</p></div><div><h4>EXPLORE</h4><a href="#characters">Characters ↗</a><a href="#jokes">Jokes ↗</a><a href="#activities">Activities ↗</a></div><div><h4>DATA SOURCES</h4><a href="https://rickandmortyapi.com/" target="_blank" rel="noopener">Rick and Morty ↗</a><a href="https://v2.jokeapi.dev/" target="_blank" rel="noopener">JokeAPI ↗</a><a href="https://bored-api.appbrewery.com/" target="_blank" rel="noopener">Bored API ↗</a></div></div><div class="shell footer-bottom"><span>© {{new Date().getFullYear()}} VANTA FUN. Independent student project.</span><a href="#top">BACK TO TOP ↑</a></div></footer>
 <div v-if="copied" class="toast" role="status">Joke copied!</div><div v-if="selected" class="modal-backdrop" @click.self="closeDetails"><div class="modal" role="dialog" aria-modal="true" aria-labelledby="detail-title"><button ref="modalClose" class="modal-close" aria-label="Close" @click="closeDetails">✕</button><img v-if="selected.image" :src="characterImage(selected)" :alt="selected.name" @error="imageFailed"><div class="modal-body"><span class="section-kicker">{{selected.kind==='character'?'CHARACTER PROFILE':selected.kind==='joke'?'JOKE DETAILS':'ACTIVITY DETAILS'}}</span><template v-if="selected.kind==='character'"><h2 id="detail-title">{{selected.name}}</h2><p>Status: {{selected.status}}</p><p>Species: {{selected.species}}</p><p>Gender: {{selected.gender}}</p><p>Origin: {{selected.origin?.name||'Unknown'}}</p><p>Location: {{selected.location?.name||'Unknown'}}</p><p>Episodes: {{selected.episode?.length||0}}</p></template><template v-else-if="selected.kind==='joke'"><h2 id="detail-title">{{selected.category}} joke</h2><p>{{selected.type==='twopart'?selected.setup:selected.joke}}</p><p v-if="selected.type==='twopart'">{{selected.delivery}}</p><p>Format: {{selected.type==='twopart'?'Two-part':'Single'}}</p><button class="secondary-btn" @click="copyJoke(selected)">Copy joke ⧉</button></template><template v-else><h2 id="detail-title">{{selected.activity}}</h2><p>Category: {{selected.type||'General'}}</p><p>Participants: {{selected.participants||1}}</p><p v-if="selected.accessibility!=null">Accessibility: {{selected.accessibility}}</p><p v-if="selected.price!=null">Cost indicator: {{selected.price}}</p></template></div></div></div>
</div>
</template>